190			if (!pending) {
191				logger.warn(LogType.CLUSTER, `Cannot reject unknown request ${request_id}`);
192				return false;
193			}
194	
195			clearTimeout(pending.timeout);
196			this.pendingRequests.delete(request_id);
197			this.onSettle?.(request_id);
198	
