213		 * Clear all pending requests (useful for testing or shutdown)
214		 */
215		clearAll(): void {
216			for (const pending of this.pendingRequests.values()) {
217				clearTimeout(pending.timeout);
218				pending.reject(new Error("Request tracker cleared"));
219			}
220			this.pendingRequests.clear();
221			this.lateSuccesses.clear();
222			logger.info(LogType.CLUSTER, "All pending requests cleared");
223		}
