import * as grpc from "@grpc/grpc-js";
import { LogType, logger } from "../../../shared/Logger.js";

export interface RateLimitRule {
	maxRequests: number;
	windowMs: number;
}

export interface GrpcRateLimiterOptions {
	moduleRule: RateLimitRule;
	rpcRules?: Record<string, Partial<RateLimitRule>>;
	/**
	 * Techo de peticiones EN VUELO por módulo. `0` o ausente = sin techo.
	 *
	 * Es el freno que faltaba, y es distinto del de TASA: la tasa cuenta cuántas
	 * ENTRAN por ventana, y en el incidente del 11-08-2026 los ~115 req/s reales
	 * quedaron muy por debajo del techo de 300/s, así que no se activó nunca. Lo que
	 * tumbó al core no fue el ritmo de entrada: fue la ACUMULACIÓN — con 5 s de
	 * deadline y un core que ya no contestaba, llegó a tener del orden de 575
	 * peticiones vivas a la vez, cada una reteniendo su payload y su closure.
	 *
	 * En tráfico sano las peticiones en vuelo de un módulo son unidades: entran a
	 * ~100/s y se resuelven en decenas de milisegundos. Un techo alto no molesta a
	 * nadie y corta en seco al módulo desbocado, que es justo lo que se quiere —
	 * porque el core lo comparten los diez módulos y ahogarlo se los lleva a todos.
	 */
	maxInFlightPerModule?: number;
	logger?: typeof logger;
	logType?: string;
}

export interface RateLimitDecision {
	allowed: boolean;
	retryAfterMs: number;
	reason: "module" | "rpc" | "in_flight" | "none";
}

type BucketState = {
	windowStart: number;
	count: number;
};

type UnaryHandler<Req, Res> = (call: grpc.ServerUnaryCall<Req, Res>, callback: grpc.sendUnaryData<Res>) => void;

function sanitizeRule(rule: Partial<RateLimitRule> | undefined, fallback: RateLimitRule): RateLimitRule {
	const maxRequests = Number(rule?.maxRequests ?? fallback.maxRequests);
	const windowMs = Number(rule?.windowMs ?? fallback.windowMs);

	return {
		maxRequests: Number.isFinite(maxRequests) ? Math.max(1, Math.floor(maxRequests)) : fallback.maxRequests,
		windowMs: Number.isFinite(windowMs) ? Math.max(1_000, Math.floor(windowMs)) : fallback.windowMs
	};
}

export class GrpcRateLimiter {
	private readonly moduleRule: RateLimitRule;
	private readonly rpcRules: Map<string, RateLimitRule>;
	private readonly buckets = new Map<string, BucketState>();
	private readonly logger: typeof logger;
	private readonly logType: string;
	private readonly metrics = {
		allowed: 0,
		blocked: 0,
		byRpc: new Map<string, { allowed: number; blocked: number }>()
	};
	/** Peticiones vivas por módulo. Sube al admitir y baja al responder. */
	private readonly inFlight = new Map<string, number>();
	private readonly maxInFlightPerModule: number;
	/** Rechazos por techo de concurrencia en el periodo, para la línea de carga. */
	private inFlightRejections = 0;
	/** Máximo simultáneo visto en el periodo: es el número con el que calibrar. */
	private inFlightPeak = 0;

	constructor(options: GrpcRateLimiterOptions) {
		this.moduleRule = sanitizeRule(options.moduleRule, { maxRequests: 120, windowMs: 60_000 });
		this.rpcRules = new Map(
			Object.entries(options.rpcRules || {}).map(([rpc, rule]) => [rpc, sanitizeRule(rule, this.moduleRule)])
		);
		this.logger = options.logger ?? logger;
		this.logType = options.logType ?? LogType.GRPC;
		const ceiling = Number(options.maxInFlightPerModule ?? 0);
		this.maxInFlightPerModule = Number.isFinite(ceiling) && ceiling > 0 ? Math.floor(ceiling) : 0;
	}

	/**
	 * Reserva un hueco de concurrencia, o `false` si el módulo ya está en su techo.
	 *
	 * Va SEPARADO de `checkAndConsume` porque su contrapartida (`releaseInFlight`)
	 * tiene que correr cuando la petición se resuelve, y eso sólo lo sabe quien
	 * envuelve el handler. Un llamante que use `checkAndConsume` a pelo no participa
	 * del techo — es explícito, no un olvido.
	 */
	public tryAcquireInFlight(moduleKey: string): boolean {
		const live = this.inFlight.get(moduleKey) ?? 0;
		if (this.maxInFlightPerModule > 0 && live >= this.maxInFlightPerModule) {
			this.inFlightRejections++;
			return false;
		}
		const next = live + 1;
		this.inFlight.set(moduleKey, next);
		if (next > this.inFlightPeak) this.inFlightPeak = next;
		return true;
	}

	public releaseInFlight(moduleKey: string): void {
		const live = (this.inFlight.get(moduleKey) ?? 0) - 1;
		// Se borra la entrada al llegar a cero: si no, el mapa acumularía una clave
		// por cada módulo que haya hablado alguna vez desde el arranque.
		if (live <= 0) this.inFlight.delete(moduleKey);
		else this.inFlight.set(moduleKey, live);
	}

	/** Peticiones vivas de un módulo (o de todos si no se da). Para tests y métricas. */
	public getInFlight(moduleKey?: string): number {
		if (moduleKey !== undefined) return this.inFlight.get(moduleKey) ?? 0;
		let total = 0;
		for (const live of this.inFlight.values()) total += live;
		return total;
	}

