// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * docs/AUDITORIA-limites-grpc-2026-08-11.md, hallazgo #1 (mitad de
 * `pendingRequests`): sin `maxPending`, cada entrada retiene sus closures,
 * un Timeout y el payload completo mientras se espera al worker — si las
 * peticiones entran más rápido de lo que se resuelven, el Map crece sin
 * freno. Estos tests pinan el contrato del techo.
 */
describe("RequestTracker — techo de pendingRequests (maxPending)", () => {
	let tracker: InstanceType<typeof RequestTracker>;

	beforeEach(() => {
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects new requests once the tracker is at capacity, without growing the pending count", async () => {
		tracker = new RequestTracker(30000, 2);

		const p1 = tracker.trackRequest("trace-1");
		const p2 = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(2);

		await expect(tracker.trackRequest("trace-3")).rejects.toThrow(/capacity/);
		// The rejected request never entered the map — capacity stays at 2.
		expect(tracker.getPendingCount()).toBe(2);

		tracker.resolveRequest("trace-1", { success: true } as MessageResponseIPC);
		tracker.resolveRequest("trace-2", { success: true } as MessageResponseIPC);
		await expect(p1).resolves.toBeDefined();
		await expect(p2).resolves.toBeDefined();
	});

	it("frees a slot once a pending request settles (resolve, reject, or timeout)", async () => {
		tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("trace-1", 100);
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/capacity/);

		vi.advanceTimersByTime(150);
		await expect(p1).rejects.toThrow(/timed out/);

		// The slot vacated by the timeout is available again.
		const p2 = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(1);
		tracker.resolveRequest("trace-2", { success: true } as MessageResponseIPC);
		await expect(p2).resolves.toBeDefined();
	});

	it("a trace_id collision frees its own slot before the capacity check, so re-tracking the same id at the cap still succeeds", async () => {
		tracker = new RequestTracker(30000, 1);

		const prior = tracker.trackRequest("trace-1");
		const next = tracker.trackRequest("trace-1");

		await expect(prior).rejects.toThrow(/superseded/);
		expect(tracker.getPendingCount()).toBe(1);

		tracker.resolveRequest("trace-1", { success: true } as MessageResponseIPC);
		await expect(next).resolves.toBeDefined();
	});

	it("defaults to a generous cap so normal traffic is never rejected", () => {
		tracker = new RequestTracker(30000);
		for (let i = 0; i < 500; i++) tracker.trackRequest(`trace-${i}`);
		expect(tracker.getPendingCount()).toBe(500);
	});
});

