		tracker.resolveRequest("trace-2", { success: true } as MessageResponseIPC);
		await expect(p1).resolves.toBeDefined();
		await expect(p2).resolves.toBeDefined();
	});

	it("frees a slot once a pending request settles (resolve, reject, or timeout)", async () => {
		tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("trace-1", 100);
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/capacity/);

		vi.advanceTimersByTime(150);
		await expect(p1).rejects.toThrow(/timed out/);

		// The slot vacated by the timeout is available again.
		const p2 = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(1);
		tracker.resolveRequest("trace-2", { success: true } as MessageResponseIPC);
		await expect(p2).resolves.toBeDefined();
	});

	it("a trace_id collision frees its own slot before the capacity check, so re-tracking the same id at the cap still succeeds", async () => {
		tracker = new RequestTracker(30000, 1);

		const prior = tracker.trackRequest("trace-1");
		const next = tracker.trackRequest("trace-1");

		await expect(prior).rejects.toThrow(/superseded/);
		expect(tracker.getPendingCount()).toBe(1);

		tracker.resolveRequest("trace-1", { success: true } as MessageResponseIPC);
		await expect(next).resolves.toBeDefined();
	});

	it("defaults to a generous cap so normal traffic is never rejected", () => {
		tracker = new RequestTracker(30000);
		for (let i = 0; i < 500; i++) tracker.trackRequest(`trace-${i}`);
		expect(tracker.getPendingCount()).toBe(500);
	});
});
